export const GLOSSARY_SHARD = Object.freeze({"proof-of-stake":{"slug":"proof-of-stake","cat":"basics","en":"Proof of stake (PoS)","contentLocale":"vi","term":"Bằng chứng cổ phần (Proof of Stake - PoS)","aka":["PoS","proof of stake","bằng chứng cổ phần"],"short":"Bằng chứng cổ phần (Proof of Stake, PoS) là cơ chế đồng thuận trong đó validator khóa coin của mạng làm tài sản đảm bảo để được quyền đề xuất và xác thực khối mới, thay cho việc đào bằng máy.","body":[["Thay vì cạnh tranh bằng điện năng như ",["PoW","proof-of-work"],", mạng PoS chọn ",["validator","validator"]," dựa trên lượng coin họ đã stake. Validator làm đúng sẽ nhận thưởng; làm sai, ví dụ ký hai khối mâu thuẫn, có thể bị phạt cắt một phần tài sản (slashing)."],[["Ethereum","ethereum"]," chuyển sang PoS từ tháng 9 năm 2022. Solana, Cardano, Avalanche và nhiều ",["blockchain","blockchain"]," khác cũng dùng các biến thể PoS. Mỗi mạng có quy tắc riêng về số coin tối thiểu, thời gian chờ rút (unbonding) và mức phạt."],["Người dùng thường không tự chạy validator mà tham gia ",["staking","staking"]," qua sàn, qua ví ủy quyền (delegation) hoặc qua liquid staking. Mỗi cách có rủi ro khác nhau: rủi ro sàn, rủi ro ",["hợp đồng thông minh","smart-contract"],", rủi ro validator bị phạt và rủi ro giá coin giảm trong lúc bị khóa."]],"example":"Giả sử một mạng PoS có tổng cộng 30 triệu coin đang được stake và bạn stake 3.000 coin, tức 0,01% tổng lượng stake. Nếu mạng phát hành 1,5 triệu coin thưởng mỗi năm cho người stake, phần của bạn trước phí là 1,5 triệu × 0,01% = 150 coin, tương đương 5% mỗi năm. Nếu validator bạn chọn lấy hoa hồng 10%, bạn nhận khoảng 135 coin. Nếu giá coin giảm 20% trong năm, phần thưởng này không bù được khoản lỗ giá.","mistakes":["Nghĩ rằng phần thưởng staking là lãi suất cố định không có rủi ro.","Quên thời gian chờ rút, nên không bán được ngay khi thị trường biến động mạnh.","Chọn validator chỉ vì phí hoa hồng thấp mà không xem lịch sử hoạt động và nguy cơ bị phạt."],"faq":[{"q":"PoS có an toàn bằng PoW không?","a":"Hai cơ chế bảo vệ mạng theo cách khác nhau: PoW dựa vào chi phí điện và phần cứng, PoS dựa vào giá trị tài sản bị khóa và có thể bị phạt. Mức an toàn phụ thuộc vào quy mô và độ phân tán của từng mạng."},{"q":"Muốn tham gia PoS có cần máy mạnh không?","a":"Nếu chỉ ủy quyền hoặc staking qua sàn thì không. Chạy validator riêng mới cần máy chủ ổn định, kết nối mạng tốt và đủ số coin tối thiểu."}],"title":"Proof of Stake (PoS) là gì? Bằng chứng cổ phần","description":"Proof of Stake là gì, validator được chọn thế nào, slashing là gì và staking theo cơ chế PoS có những rủi ro nào.","related":[["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó."],["liquid-staking","Staking thanh khoản (Liquid staking)","Staking thanh khoản là cách stake coin qua một giao thức và nhận lại token đại diện như stETH, có thể giao dịch hoặc dùng trong DeFi trong khi coin gốc vẫn đang được stake."],["proof-of-work","Bằng chứng công việc (Proof of Work - PoW)","Bằng chứng công việc (Proof of Work, PoW) là cơ chế đồng thuận trong đó thợ đào dùng sức mạnh tính toán để giải bài toán mật mã, ai tìm ra lời giải trước sẽ được thêm khối mới và nhận thưởng."],["validator","Validator (trình xác thực)","Validator (trình xác thực) là node trên blockchain bằng chứng cổ phần, khóa coin làm tài sản đảm bảo để đề xuất, kiểm tra và bỏ phiếu cho các khối mới, đổi lại nhận phần thưởng."],["ethereum","Ethereum (ETH)","Ethereum là blockchain cho phép chạy hợp đồng thông minh và ứng dụng phi tập trung, còn ETH (Ether) là đồng coin gốc dùng để trả phí gas và staking trên mạng này."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"volatility":{"slug":"volatility","cat":"basics","en":"Volatility","contentLocale":"vi","term":"Biến động giá (Volatility)","aka":["volatility","độ biến động","biến động"],"short":"Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh.","body":[["Biến động thường được đo bằng độ lệch chuẩn của lợi nhuận, quy ra theo năm. Crypto nói chung biến động mạnh hơn cổ phiếu hay vàng, và ",["altcoin","altcoin"]," nhỏ thường biến động mạnh hơn ",["BTC","bitcoin"],". ",["Stablecoin","stablecoin"]," được thiết kế để có biến động gần như bằng không so với đồng định giá."],["Biến động là con dao hai lưỡi: nó tạo cơ hội lợi nhuận nhưng cũng làm lỗ nhanh. Với ",["đòn bẩy","leverage"],", biến động quyết định khoảng cách an toàn đến ",["giá thanh lý","liquidation-price"],". Một cú giảm 5% trong vài phút là bình thường với nhiều coin, và đủ để ",["cháy tài khoản","liquidation"]," dùng đòn bẩy 20x."],"Hãy dùng biến động để quyết định kích thước lệnh và vị trí cắt lỗ. Tài sản biến động mạnh cần lệnh nhỏ hơn và cắt lỗ rộng hơn. Các chỉ báo như ATR hay Bollinger Bands giúp ước lượng biên độ dao động thông thường."],"example":"Giả sử coin A thường dao động khoảng 2% mỗi ngày, còn coin B khoảng 8% mỗi ngày. Bạn chấp nhận mất tối đa 100 USDT mỗi lệnh và đặt cắt lỗ cách giá vào bằng một ngày dao động. Với A, cắt lỗ cách 2%, nên kích thước lệnh là 100 / 0,02 = 5.000 USDT. Với B, cắt lỗ cách 8%, nên lệnh chỉ nên là 100 / 0,08 = 1.250 USDT. Cùng mức rủi ro, nhưng lệnh với coin biến động mạnh nhỏ hơn 4 lần.","mistakes":["Dùng cùng kích thước lệnh cho mọi coin bất kể mức biến động.","Đặt cắt lỗ quá sát với coin biến động mạnh, bị quét ra liên tục.","Dùng đòn bẩy cao trong lúc thị trường có tin lớn khiến biến động tăng vọt."],"faq":[{"q":"Vì sao crypto biến động mạnh?","a":"Thị trường còn tương đối nhỏ, giao dịch 24/7, nhiều người dùng đòn bẩy và thanh khoản ở nhiều coin còn mỏng. Tin tức và các đợt thanh lý dây chuyền cũng khuếch đại biến động."},{"q":"Biến động cao là tốt hay xấu?","a":"Không tốt hay xấu tự thân. Nó có nghĩa là rủi ro và cơ hội đều lớn hơn, nên bạn cần điều chỉnh kích thước lệnh và đòn bẩy cho phù hợp."}],"title":"Volatility là gì? Biến động giá trong crypto","description":"Biến động giá (volatility) là gì, vì sao crypto biến động mạnh và cách dùng biến động để chọn kích thước lệnh, cắt lỗ.","related":[["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["position-sizing","Quản lý khối lượng vị thế (Position sizing)","Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"stop-limit-order":{"slug":"stop-limit-order","cat":"trading","en":"Stop-limit order","contentLocale":"vi","term":"Lệnh dừng giới hạn (Stop-limit)","aka":["stop limit","lệnh stop-limit","lệnh dừng giới hạn"],"short":"Lệnh dừng giới hạn (stop-limit) là lệnh có hai mức giá: khi giá chạm giá kích hoạt (stop), sàn đặt một lệnh giới hạn ở giá giới hạn (limit) bạn đã chọn, thay vì một lệnh thị trường.","body":[["Bạn nhập giá kích hoạt và giá giới hạn. Trước khi giá chạm mức kích hoạt, lệnh không nằm trong ",["sổ lệnh","order-book"],". Khi được kích hoạt, nó trở thành ",["lệnh giới hạn","limit-order"]," bình thường và chỉ khớp ở giá giới hạn hoặc tốt hơn."],"Ưu điểm là kiểm soát giá: bạn không bị khớp ở mức tệ khi thị trường rơi đột ngột. Nhược điểm nghiêm trọng là lệnh có thể không khớp. Nếu giá lao qua cả giá giới hạn, vị thế của bạn vẫn mở và tiếp tục lỗ.",["Để tăng khả năng khớp khi dùng làm ",["cắt lỗ","stop-loss"],", nhiều người đặt giá giới hạn kém hơn giá kích hoạt một khoảng, ví dụ kích hoạt ở 100 và giới hạn ở 99,5. Stop-limit cũng có thể dùng để mua khi giá phá lên một mức kháng cự. Tên gọi và cách kích hoạt khác nhau giữa các sàn."]],"example":["Bạn giữ 50 token mua ở 20 ",["USDT","usdt"]," và đặt stop-limit bán: kích hoạt 18 USDT, giới hạn 17,8 USDT. Nếu giá giảm từ từ, lệnh kích hoạt ở 18 và khớp quanh 17,8 đến 18, bạn lỗ khoảng 100 đến 110 USDT. Nhưng nếu có tin xấu và giá rơi thẳng từ 18,1 xuống 16, lệnh giới hạn ở 17,8 có thể không khớp. Khi đó phần 50 token trị giá 800 USDT, lỗ 200 USDT và vẫn đang mở."],"mistakes":["Đặt giá giới hạn bằng đúng giá kích hoạt, khiến lệnh dễ bị bỏ qua khi giá rơi nhanh.","Nghĩ rằng stop-limit bảo vệ giống hệt lệnh cắt lỗ thị trường.","Không kiểm tra lại vị thế sau những cú giảm mạnh để xem lệnh đã khớp chưa."],"faq":[{"q":"Stop-limit khác stop-market thế nào?","a":"Stop-market gửi lệnh thị trường khi kích hoạt nên gần như chắc chắn khớp nhưng không kiểm soát giá. Stop-limit gửi lệnh giới hạn nên kiểm soát giá nhưng có thể không khớp."},{"q":"Nên đặt giá giới hạn cách giá kích hoạt bao xa?","a":"Tùy độ biến động và thanh khoản của cặp. Khoảng cách rộng hơn tăng khả năng khớp nhưng chấp nhận giá kém hơn."}],"title":"Lệnh stop-limit là gì? Khác stop-market ra sao","description":"Lệnh dừng giới hạn (stop-limit) là gì, cách đặt giá kích hoạt và giá giới hạn, và vì sao lệnh có thể không khớp.","related":[["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."],["trailing-stop","Lệnh cắt lỗ động (Trailing stop)","Lệnh cắt lỗ động (trailing stop) là lệnh dừng có giá kích hoạt tự động di chuyển theo giá khi giá đi đúng hướng, giữ một khoảng cách cố định, và chỉ kích hoạt khi giá đảo chiều đủ khoảng cách đó."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Chốt lời và cắt lỗ là kế hoạch, không phải bảo hiểm"},"coin":null,"tool":null,"cta":false},"time-in-force":{"slug":"time-in-force","cat":"trading","en":"Time in force (GTC, IOC, FOK)","contentLocale":"vi","term":"Hiệu lực lệnh (Time in force: GTC, IOC, FOK)","aka":["time in force","GTC","IOC","FOK"],"short":"Time in force (hiệu lực lệnh) là thiết lập quy định một lệnh giới hạn tồn tại bao lâu và xử lý thế nào nếu không khớp ngay, phổ biến nhất là GTC, IOC và FOK.","body":["GTC (Good Till Cancelled) giữ lệnh trong sổ cho đến khi khớp hết hoặc bạn tự hủy; đây là mặc định trên nhiều sàn. IOC (Immediate Or Cancel) khớp ngay phần có thể khớp, phần còn lại bị hủy. FOK (Fill Or Kill) yêu cầu khớp toàn bộ ngay lập tức, nếu không thì hủy cả lệnh.",["Chọn đúng hiệu lực giúp bạn tránh các tình huống không mong muốn. GTC phù hợp khi bạn chờ giá về một mức. IOC hữu ích khi muốn lấy ",["thanh khoản","liquidity"]," đang có mà không để lại lệnh dư. FOK dùng khi bạn cần đủ số lượng, ví dụ trong chiến lược chênh lệch giá, nếu không thì thà không làm."],["Một số sàn có thêm tùy chọn như GTD (có hiệu lực đến một thời điểm) hoặc gộp ",["post-only","post-only-order"]," vào danh sách này. Tên gọi và mặc định khác nhau giữa các sàn, nên hãy kiểm tra trong phần cài đặt lệnh."]],"example":[["Sổ lệnh","order-book"]," phía bán có 0,6 ",["BTC","bitcoin"]," ở 61.000 và 1 BTC ở 61.050. Bạn đặt mua giới hạn 1 BTC ở 61.000. Với GTC: 0,6 BTC khớp ngay, 0,4 BTC còn lại nằm chờ ở 61.000. Với IOC: 0,6 BTC khớp, tốn 36.600 ",["USDT","usdt"],", còn 0,4 BTC bị hủy. Với FOK: vì không đủ 1 BTC ở mức 61.000 hoặc thấp hơn, cả lệnh bị hủy và bạn không mua được gì."],"mistakes":["Để lệnh GTC cũ trong sổ rồi quên, bị khớp nhiều tuần sau khi tình hình đã khác.","Dùng FOK cho lệnh lớn trên cặp thanh khoản thấp và thắc mắc vì sao lệnh luôn bị hủy.","Không biết sàn đang mặc định hiệu lực nào cho lệnh giới hạn."],"faq":[{"q":"GTC nghĩa là gì?","a":"GTC là Good Till Cancelled, lệnh có hiệu lực đến khi khớp hết hoặc bạn hủy. Một số sàn vẫn có thể tự hủy lệnh rất cũ theo quy định riêng."},{"q":"IOC khác FOK thế nào?","a":"IOC cho phép khớp một phần rồi hủy phần còn lại, còn FOK chỉ chấp nhận khớp toàn bộ ngay lập tức, nếu không thì hủy cả lệnh."}],"title":"GTC, IOC, FOK là gì? Hiệu lực lệnh giao dịch","description":"Time in force là gì, phân biệt GTC, IOC và FOK bằng ví dụ cụ thể và cách chọn hiệu lực lệnh phù hợp.","related":[["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."],["post-only-order","Lệnh chỉ đặt (Post-only)","Lệnh post-only là lệnh giới hạn chỉ được chấp nhận nếu nó nằm chờ trong sổ lệnh làm maker; nếu lệnh sẽ khớp ngay và trở thành taker, sàn tự động hủy hoặc điều chỉnh nó."],["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Thị trường, giới hạn, hủy lệnh: mỗi loại giải quyết điều gì?"},"coin":null,"tool":null,"cta":false},"private-key":{"slug":"private-key","cat":"wallets-security","en":"Private key","contentLocale":"vi","term":"Khóa riêng tư (Private key)","aka":["private key","khóa bí mật"],"short":"Khóa riêng tư là một số bí mật rất lớn dùng để ký giao dịch và chứng minh bạn sở hữu một địa chỉ ví; ai biết khóa này có thể chuyển toàn bộ tài sản đi.","body":[["Mỗi ",["địa chỉ ví","wallet-address"]," gắn với một cặp khóa: khóa riêng tư giữ bí mật và ",["khóa công khai","public-key"]," có thể chia sẻ. Khi bạn gửi coin, ví dùng khóa riêng tư để tạo chữ ký số; ",["mạng lưới","blockchain-network"]," kiểm tra chữ ký bằng khóa công khai mà không cần biết khóa riêng tư."],["Khóa riêng tư thường hiển thị dưới dạng chuỗi 64 ký tự hex. Hầu hết ví hiện đại không bắt bạn ghi từng khóa mà sinh chúng từ ",["cụm từ khôi phục","seed-phrase"],", nhưng vẫn cho phép xuất khóa của một địa chỉ cụ thể."],"Câu nói quen thuộc “not your keys, not your coins” nghĩa là nếu bạn không giữ khóa riêng tư, như khi để coin trên sàn, thì về kỹ thuật bên giữ khóa mới kiểm soát tài sản."],"example":["Giả sử bạn có hai địa chỉ trong cùng một ví: địa chỉ A chứa 1 ",["ETH","ethereum"],", địa chỉ B chứa 500 ",["USDC","usdc"],". Bạn xuất khóa riêng tư của địa chỉ A để nhập vào một ví khác và vô tình dán nó vào một trang giả mạo. Kẻ gian rút được 1 ETH ở địa chỉ A, nhưng 500 USDC ở địa chỉ B vẫn an toàn vì chúng dùng khóa khác. Nếu bạn dán cả cụm từ khôi phục, cả hai địa chỉ đều mất."],"mistakes":["Gửi khóa riêng tư cho “nhân viên hỗ trợ” để họ “kiểm tra ví” giúp.","Lưu khóa riêng tư trong file văn bản trên máy tính có cài phần mềm không rõ nguồn gốc.","Nghĩ rằng đổi mật khẩu ứng dụng ví sẽ vô hiệu hóa một khóa riêng tư đã bị lộ."],"faq":[{"q":"Khóa riêng tư bị lộ thì phải làm gì?","a":"Tạo ví mới với cụm từ khôi phục mới và chuyển ngay toàn bộ tài sản sang đó. Khóa đã lộ thì không thể thu hồi hay đổi."},{"q":"Có thể đoán ra khóa riêng tư từ địa chỉ ví không?","a":"Không, với công nghệ hiện nay việc tính ngược từ địa chỉ hay khóa công khai ra khóa riêng tư là không khả thi trên thực tế."}],"title":"Khóa riêng tư (private key) là gì trong crypto?","description":"Khóa riêng tư là gì, khác khóa công khai và cụm từ khôi phục thế nào, và bạn phải làm gì khi private key bị lộ.","related":[["seed-phrase","Cụm từ khôi phục (Seed phrase)","Cụm từ khôi phục là chuỗi 12 hoặc 24 từ tiếng Anh dùng để tạo lại toàn bộ khóa riêng tư của ví, nên ai có nó là có toàn quyền với tài sản trong ví."],["public-key","Khóa công khai (Public key)","Khóa công khai là khóa được tính ra từ khóa riêng tư, có thể chia sẻ công khai, dùng để mọi người xác minh chữ ký của bạn và để tạo ra địa chỉ ví."],["wallet-address","Địa chỉ ví (Wallet address)","Địa chỉ ví là chuỗi ký tự công khai đại diện cho nơi nhận crypto trên một blockchain cụ thể, giống số tài khoản ngân hàng nhưng gắn với từng mạng lưới."],["multisig-wallet","Ví đa chữ ký (Multisig wallet)","Ví đa chữ ký là ví cần nhiều khóa riêng tư cùng ký, ví dụ 2 trên 3 khóa, thì giao dịch mới được thực hiện, giúp không một khóa đơn lẻ nào có thể tự di chuyển tài sản."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":null,"cta":false},"amm":{"slug":"amm","cat":"defi","en":"Automated market maker (AMM)","contentLocale":"vi","term":"Tạo lập thị trường tự động (AMM)","aka":["AMM","automated market maker","nhà tạo lập thị trường tự động"],"short":"AMM (tạo lập thị trường tự động) là cơ chế của nhiều DEX dùng công thức toán học và pool thanh khoản để định giá và khớp giao dịch, thay cho sổ lệnh mua bán truyền thống.","body":[["Trên ",["sàn tập trung","centralized-exchange"],", giá hình thành từ lệnh mua và lệnh bán trên ",["sổ lệnh","order-book"],". Trên AMM, bạn giao dịch với một pool chứa hai token. Công thức phổ biến nhất là tích không đổi x nhân y bằng k, do Uniswap phổ biến: khi bạn rút một token ra, bạn phải bỏ token kia vào sao cho tích số lượng hai token giữ nguyên."],["Hệ quả: lệnh càng lớn so với pool thì giá bạn nhận càng xấu, gọi là tác động giá. Pool sâu thì ",["trượt giá","slippage"]," ít. Mỗi giao dịch trả một khoản phí nhỏ cho những người cung cấp ",["thanh khoản","liquidity"],"."],["Các biến thể khác gồm AMM cho ",["stablecoin","stablecoin"]," như Curve với đường cong phẳng hơn quanh giá 1, và thanh khoản tập trung trong Uniswap v3, nơi nhà cung cấp chọn khoảng giá cụ thể. Giá trên AMM được giữ sát thị trường nhờ các nhà ",["arbitrage","arbitrage"],"."]],"example":"Giả sử pool có 100 ETH và 300.000 USDC, giá ngầm là 3.000 USDC mỗi ETH, k bằng 30.000.000. Bạn bỏ vào 30.000 USDC để mua ETH. Pool lúc này có 330.000 USDC, nên ETH còn lại là 30.000.000 chia 330.000, khoảng 90,91 ETH. Bạn nhận khoảng 9,09 ETH, giá trung bình khoảng 3.300 USDC, cao hơn giá ban đầu 10% (chưa tính phí).","mistakes":["Nghĩ rằng giá hiển thị trước khi swap là giá chắc chắn cho cả lệnh lớn.","Đổi số tiền lớn trong pool nhỏ mà không xem chỉ số tác động giá.","Cho rằng AMM luôn có giá giống sàn tập trung, trong khi chênh lệch có thể lớn với pool mỏng."],"faq":[{"q":"AMM khác sổ lệnh như thế nào?","a":"Sổ lệnh khớp người mua với người bán theo giá họ đặt, còn AMM để bạn giao dịch với pool theo công thức. AMM luôn có giá để giao dịch, nhưng giá xấu đi nhanh khi lệnh lớn."},{"q":"Ai giữ giá trên AMM sát thị trường?","a":"Các nhà arbitrage mua bán khi giá trên pool lệch khỏi giá thị trường, kéo giá pool về gần giá chung và thu lợi từ phần chênh lệch."}],"title":"AMM là gì? Tạo lập thị trường tự động trên DEX","description":"AMM là gì, công thức x nhân y bằng k hoạt động thế nào, vì sao lệnh lớn bị tác động giá và các loại AMM phổ biến.","related":[["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí."],["impermanent-loss","Tổn thất tạm thời (Impermanent loss)","Tổn thất tạm thời là phần giá trị bạn bị thiệt khi cung cấp thanh khoản cho pool so với việc chỉ giữ nguyên hai token, phát sinh khi giá của chúng thay đổi lệch nhau."],["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."],["slippage","Trượt giá (Slippage)","Trượt giá (slippage) là phần chênh lệch giữa giá bạn dự kiến khi đặt lệnh và giá khớp thực tế, xảy ra khi thanh khoản không đủ hoặc giá thay đổi trong lúc lệnh đang được xử lý."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"staking":{"slug":"staking","cat":"defi","en":"Staking","contentLocale":"vi","term":"Staking","aka":["stake","đặt cược","khóa coin nhận lãi"],"short":"Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó.","body":[["Trên các mạng proof-of-stake như ",["Ethereum","ethereum"],", Solana hay Cardano, ",["validator","validator"]," đặt cược coin để có quyền đề xuất và ",["xác nhận","block-confirmations"]," khối. Bạn có thể tự chạy validator, ủy quyền coin cho validator khác, stake qua sàn, hoặc dùng ",["staking thanh khoản","liquid-staking"],". Mỗi cách khác nhau về độ khó, phí và quyền kiểm soát."],["Phần thưởng đến từ phát hành mới và phí giao dịch, thường được hiển thị dưới dạng ",["APR","apr-vs-apy"]," hoặc APY và thay đổi theo ",["mạng lưới","blockchain-network"],". Rủi ro gồm: giá coin giảm mạnh hơn phần thưởng, thời gian chờ rút stake, slashing khi validator vi phạm, và rủi ro bên trung gian nếu stake qua sàn."],"Trên sàn, sản phẩm “staking” đôi khi thực chất là sản phẩm tiết kiệm hay cho vay mang tên staking. Hãy đọc mô tả để biết tiền thật sự được dùng vào đâu."],"example":"Giả sử bạn stake 100 SOL với mức thưởng giả định 7% APR. Sau một năm, bạn nhận khoảng 7 SOL, có 107 SOL. Nếu giá SOL giả định giảm từ 150 USD xuống 120 USD, giá trị chuyển từ 15.000 USD thành 12.840 USD. Bạn có thêm coin nhưng vẫn lỗ tính theo USD, vì phần thưởng không bù được mức giảm 20%.","mistakes":["Nghĩ rằng staking là “lãi không rủi ro” mà quên giá coin có thể giảm nhiều hơn phần thưởng.","Không biết thời gian chờ rút stake, rồi cần tiền gấp mà không rút được ngay.","Chọn validator chỉ vì phí thấp nhất mà không xem lịch sử hoạt động."],"faq":[{"q":"Staking trên sàn có an toàn không?","a":"Tiện lợi nhưng bạn chịu thêm rủi ro bên trung gian vì sàn giữ coin. Đổi lại bạn không phải tự quản lý validator hay ví."},{"q":"Staking có bị mất coin không?","a":"Có thể bị trừ một phần nếu validator bị slashing do vi phạm quy tắc. Ngoài ra, giá trị tính theo tiền pháp định vẫn biến động theo giá coin."}],"title":"Staking là gì? Cách stake coin nhận thưởng","description":"Staking là gì, phần thưởng đến từ đâu, các cách stake qua ví, sàn, staking thanh khoản và rủi ro bạn cần hiểu trước.","related":[["proof-of-stake","Bằng chứng cổ phần (Proof of Stake - PoS)","Bằng chứng cổ phần (Proof of Stake, PoS) là cơ chế đồng thuận trong đó validator khóa coin của mạng làm tài sản đảm bảo để được quyền đề xuất và xác thực khối mới, thay cho việc đào bằng máy."],["liquid-staking","Staking thanh khoản (Liquid staking)","Staking thanh khoản là cách stake coin qua một giao thức và nhận lại token đại diện như stETH, có thể giao dịch hoặc dùng trong DeFi trong khi coin gốc vẫn đang được stake."],["validator","Validator (trình xác thực)","Validator (trình xác thực) là node trên blockchain bằng chứng cổ phần, khóa coin làm tài sản đảm bảo để đề xuất, kiểm tra và bỏ phiếu cho các khối mới, đổi lại nhận phần thưởng."],["crypto-earn","Earn (sản phẩm tiết kiệm crypto)","Earn là nhóm sản phẩm trên sàn cho phép bạn gửi crypto để nhận lãi, gồm gửi linh hoạt, gửi kỳ hạn, staking và các sản phẩm có cấu trúc."],["apr-vs-apy","APR và APY","APR là lãi suất năm chưa tính lãi kép, còn APY là lợi suất năm đã tính lãi kép; cùng một mức lãi, APY luôn bằng hoặc cao hơn APR nếu lãi được cộng dồn."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"total-value-locked":{"slug":"total-value-locked","cat":"defi","en":"Total value locked (TVL)","contentLocale":"vi","term":"Tổng giá trị khóa (TVL)","aka":["TVL","total value locked","tổng giá trị bị khóa"],"short":"TVL (tổng giá trị khóa) là tổng giá trị tài sản crypto đang được gửi trong một giao thức DeFi hoặc một blockchain, thường tính bằng USD, dùng để đo quy mô và mức độ sử dụng.","body":[["TVL cộng giá trị mọi tài sản nằm trong hợp đồng của giao thức: tiền gửi cho vay, ",["pool thanh khoản","liquidity-pool"],", coin đang stake. Các trang tổng hợp như DefiLlama thống kê TVL theo giao thức và theo chuỗi."],["TVL hữu ích để so sánh quy mô, nhưng có nhiều điểm cần chú ý. TVL thay đổi theo giá tài sản, nên giá ",["ETH","ethereum"]," giảm thì TVL giảm dù không ai rút tiền. Cùng một tài sản có thể bị tính nhiều lần khi được dùng qua nhiều giao thức, ví dụ ",["LST","liquid-staking"]," gửi tiếp vào nền tảng cho vay. Thưởng cao có thể kéo TVL tạm thời rồi rút đi nhanh."],"TVL lớn cũng không đồng nghĩa với an toàn. Nên xem thêm doanh thu phí, số người dùng, thời gian hoạt động và lịch sử kiểm toán."],"example":["Giả sử một giao thức có TVL 500 triệu USD, trong đó 60% là ETH, tức 300 triệu USD, và 40% là ",["stablecoin","stablecoin"],". Nếu ETH giảm 20%, phần ETH còn 240 triệu USD. TVL mới là 440 triệu USD, giảm 12%, dù không có người dùng nào rút tiền. Nếu chỉ nhìn TVL, bạn có thể hiểu nhầm là dòng tiền đang rời đi."],"mistakes":["Hiểu TVL giảm luôn có nghĩa là người dùng đang rút tiền.","Coi TVL cao là bằng chứng giao thức an toàn hoặc token của nó rẻ.","Cộng TVL của nhiều giao thức mà không tính việc cùng một tài sản bị đếm lặp."],"faq":[{"q":"TVL cao có tốt không?","a":"TVL cao cho thấy nhiều vốn tin dùng giao thức, nhưng nó biến động theo giá và có thể do thưởng thu hút tạm thời. Nên đọc cùng các chỉ số khác."},{"q":"TVL khác vốn hóa thị trường thế nào?","a":"Vốn hóa là giá token nhân với nguồn cung lưu hành. TVL là giá trị tài sản người dùng gửi vào giao thức, hai con số đo hai thứ khác nhau."}],"title":"TVL là gì? Tổng giá trị khóa trong DeFi","description":"TVL (total value locked) là gì, cách tính, vì sao TVL biến động theo giá và những điểm cần chú ý khi dùng TVL đánh giá DeFi.","related":[["defi","DeFi (Tài chính phi tập trung)","DeFi (tài chính phi tập trung) là các dịch vụ tài chính như giao dịch, cho vay, gửi tiết kiệm chạy bằng hợp đồng thông minh trên blockchain, không cần ngân hàng hay sàn tập trung làm trung gian."],["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí."],["defi-lending","Cho vay DeFi (DeFi lending)","Cho vay DeFi là việc gửi crypto vào giao thức như Aave để nhận lãi, hoặc thế chấp crypto để vay tài sản khác, toàn bộ do hợp đồng thông minh quản lý thay cho ngân hàng."],["market-capitalization","Vốn hóa thị trường (Market cap)","Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"depeg":{"slug":"depeg","cat":"stablecoins","en":"Depeg","contentLocale":"vi","term":"Depeg (mất neo giá)","aka":["mất neo","mất peg","depeg stablecoin"],"short":"Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD.","body":[[["Stablecoin","stablecoin"]," được thiết kế để luôn có giá gần 1 USD nhờ tài sản dự trữ, tài sản thế chấp hoặc cơ chế thuật toán. Khi thị trường ",["nghi ngờ","fud"]," khả năng đổi lại đúng 1 USD, người nắm giữ đua nhau bán ra và giá trượt khỏi mức neo. Đó là depeg."],["Nguyên nhân thường gặp: tài sản dự trữ bị kẹt hoặc mất giá, tin đồn về nhà phát hành, ",["thanh khoản","liquidity"]," cạn trên sàn, hoặc cơ chế thuật toán sụp đổ. Không chỉ stablecoin, các token liquid ",["staking","staking"]," như stETH cũng có thể lệch khỏi giá ",["ETH","ethereum"]," khi nhiều người muốn rút cùng lúc."],["Depeg nhỏ, vài phần nghìn, xảy ra khá thường xuyên và thường tự hồi lại nhờ hoạt động ",["arbitrage","arbitrage"],". Depeg sâu và kéo dài là tín hiệu nguy hiểm, vì nó có thể kích hoạt thanh lý dây chuyền trong các giao thức cho vay dùng stablecoin đó làm tài sản thế chấp."]],"example":"Giả sử bạn giữ 10.000 USDC và nghe tin nhà phát hành có một phần dự trữ bị kẹt tại ngân hàng. Giá trên sàn rơi xuống 0,90 USD, ví của bạn lúc này chỉ còn tương đương 9.000 USD. Nếu bán hoảng loạn ở mức đó, bạn chốt khoản lỗ 1.000 USD. Nếu nhà phát hành sau đó xác nhận dự trữ vẫn đủ và giá quay về 0,999 USD, người giữ lại gần như không mất gì. Bài học là cần kiểm tra nguồn dự trữ và khả năng hoàn đổi trước khi quyết định.","mistakes":["Coi mọi stablecoin là an toàn như nhau mà không phân biệt loại có dự trữ tiền pháp định, loại thế chấp crypto và loại thuật toán.","Dồn toàn bộ tiền nhàn rỗi vào một stablecoin duy nhất thay vì chia ra vài loại.","Bán tháo ngay ở đáy của một đợt lệch giá ngắn mà không kiểm tra thông tin chính thức từ nhà phát hành."],"faq":[{"q":"USDT đã từng depeg chưa?","a":"USDT đã có vài lần giao dịch thấp hơn 1 USD trong thời gian ngắn khi thị trường căng thẳng, rồi quay lại gần mức neo. Mức lệch và thời gian khác nhau tùy từng sự kiện."},{"q":"Khi stablecoin depeg thì nên làm gì?","a":"Trước hết hãy đọc thông báo chính thức của nhà phát hành và xem cơ chế hoàn đổi còn hoạt động không. Sau đó đánh giá xem rủi ro nằm ở dự trữ, ở thanh khoản hay ở cơ chế, rồi mới quyết định giữ hay đổi sang tài sản khác."}],"title":"Depeg là gì? Stablecoin mất neo giá nghĩa là gì","description":"Depeg là khi stablecoin lệch khỏi giá 1 USD. Tìm hiểu nguyên nhân, ví dụ thực tế và cách xử lý khi stablecoin mất neo.","related":[["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["algorithmic-stablecoin","Stablecoin thuật toán","Stablecoin thuật toán là stablecoin cố giữ giá 1 USD chủ yếu bằng quy tắc phát hành và đốt token tự động, thay vì có đủ tài sản dự trữ bảo chứng phía sau."],["usdc","USDC (USD Coin)","USDC là stablecoin do công ty Circle phát hành, neo 1:1 với đô la Mỹ và được đảm bảo bằng tiền mặt cùng tài sản ngắn hạn tương đương tiền."],["liquid-staking","Staking thanh khoản (Liquid staking)","Staking thanh khoản là cách stake coin qua một giao thức và nhận lại token đại diện như stETH, có thể giao dịch hoặc dùng trong DeFi trong khi coin gốc vẫn đang được stake."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT có phải là đô la không? Tại sao mua coin lại thấy nó khắp nơi?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false},"real-world-assets":{"slug":"real-world-assets","cat":"tokenized-assets","en":"Real-world assets (RWA)","contentLocale":"vi","term":"Tài sản thực (RWA)","aka":["RWA","real-world assets","tài sản thực token hóa","tài sản thế giới thực"],"short":"Tài sản thực, hay RWA, là các tài sản ngoài blockchain như trái phiếu, vàng, bất động sản hay khoản vay được token hóa để có thể nắm giữ và giao dịch trên chuỗi.","body":[["Quy trình token hóa thường gồm ba bước: một pháp nhân nắm giữ tài sản thật, phát hành token đại diện cho quyền lợi đối với tài sản đó, và công bố thông tin về dự trữ. Các nhóm RWA phổ biến gồm ",["trái phiếu chính phủ token hóa","tokenized-treasuries"],", ",["vàng token hóa","tokenized-gold"],", tín dụng tư nhân và ",["cổ phiếu token hóa","tokenized-stocks"],"."],["RWA giúp đưa lợi suất và tài sản truyền thống vào ",["DeFi","defi"],": token có thể dùng làm tài sản thế chấp, giao dịch 24/7 và chuyển nhanh xuyên biên giới. Ondo Finance, BlackRock với quỹ BUIDL và Franklin Templeton là những cái tên thường được nhắc tới trong mảng này."],["Khác với crypto thuần, giá trị RWA phụ thuộc vào pháp nhân, đơn vị lưu ký và hệ thống pháp lý ngoài chuỗi. Nhiều sản phẩm yêu cầu ",["KYC","kyc"],", chỉ dành cho nhà đầu tư đủ điều kiện, và có ",["giới hạn khu vực","geo-restrictions"],"."]],"example":"Giả sử một token RWA đại diện cho danh mục trái phiếu ngắn hạn, lợi suất khoảng 4% mỗi năm. Bạn nắm giữ token trị giá 5.000 USDC. Sau một năm, nếu lợi suất giữ nguyên và không có phí, bạn nhận thêm khoảng 200 USD giá trị. Nhưng nếu nhà phát hành gặp vấn đề pháp lý và tạm dừng hoàn đổi, bạn có thể không rút được 5.000 USD đúng lúc cần, dù trái phiếu bên dưới vẫn an toàn.","mistakes":["Coi token RWA an toàn như tài sản gốc mà bỏ qua rủi ro của nhà phát hành.","Không kiểm tra điều kiện hoàn đổi và giới hạn KYC trước khi mua.","Nhầm token chỉ mang tên RWA với sản phẩm thật sự có tài sản bảo chứng."],"faq":[{"q":"RWA có phải xu hướng mới không?","a":"Token hóa tài sản đã được thử nghiệm nhiều năm, nhưng giai đoạn gần đây có thêm sự tham gia của các tổ chức tài chính lớn, nhất là ở mảng trái phiếu token hóa."},{"q":"Người dùng cá nhân có mua được RWA không?","a":"Có một số sản phẩm mở cho cá nhân, số khác chỉ dành cho nhà đầu tư tổ chức hoặc đủ điều kiện. Điều kiện còn phụ thuộc quốc gia bạn sống."}],"title":"RWA là gì? Token hóa tài sản thực trong crypto","description":"RWA là tài sản thực như trái phiếu, vàng được token hóa trên blockchain. Tìm hiểu cách hoạt động, ví dụ và các rủi ro chính.","related":[["tokenized-treasuries","Trái phiếu chính phủ token hóa (tokenized treasuries)","Trái phiếu chính phủ token hóa là token đại diện cho phần sở hữu trong quỹ hoặc danh mục trái phiếu kho bạc ngắn hạn, thường là của Mỹ, mang lại lợi suất ngay trên blockchain."],["tokenized-stocks","Cổ phiếu token hóa (tokenized stocks)","Cổ phiếu token hóa là token đại diện cho giá trị của một cổ phiếu niêm yết như Apple hay Tesla, thường được bảo chứng bởi cổ phiếu thật do một đơn vị lưu ký nắm giữ."],["tokenized-gold","Vàng token hóa (tokenized gold)","Vàng token hóa là token trên blockchain đại diện cho quyền sở hữu một lượng vàng vật chất cụ thể được lưu giữ trong kho, phổ biến nhất là PAXG và XAUT."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-assets","cta":false}});
